遅延読み込み

最初の画面でエディタが不要な場合は、非同期で読み込めます。

const CodeMirror = defineAsyncComponent(() => import('vue-codemirror6'));

CodeMirror は、検索・置換パネル、折りたたみマーカー、リンターのパネル、スクリーンリーダー向けの読み上げなど、独自の UI テキストを表示します。phrases プロパティに翻訳表を渡すと、これらを翻訳できます。キーは元の英語の文字列です。キーの一覧は CodeMirror の 翻訳の例 を参照してください。

翻訳表

Markdown エディタとして使い、UI を日本語に翻訳する例です。キーは、それを使うパッケージごとにまとめています。翻訳したいキーだけを書けば構いません。

<script setup lang="ts">




const value = ref('');
const lang = markdown();

/**
 * UI の翻訳(この例では日本語)
 *
 * @see {@link https://codemirror.net/examples/translate/}
 */
const phrases: Record<string, string> = {
  // @codemirror/view
  'Control character': '制御文字',
  // @codemirror/commands
  'Selection deleted': '選択範囲を削除しました',
  // @codemirror/language
  'Folded lines': '折りたたまれた行',
  'Unfolded lines': '展開された行',
  to: '〜',
  'folded code': '折りたたまれたコード',
  unfold: '展開',
  'Fold line': '行を折りたたむ',
  'Unfold line': '行を展開',
  // @codemirror/search
  'Go to line': '行へ移動',
  go: '移動',
  Find: '検索',
  Replace: '置換',
  next: '▼',
  previous: '▲',
  all: 'すべて',
  'match case': '大文字と小文字を区別',
  'by word': '単語単位',
  regexp: '正規表現',
  replace: '置換',
  'replace all': 'すべて置換',
  close: '閉じる',
